mapper.select:
SELECT t.id, t.title, t.remind_at, t.seq, p.key AS project_key
FROM tasks t
JOIN projects p ON p.id = t.project_id
WHERE t.type = 'RECORD'
  AND t.created_by = #{userId}
  AND t.remind_at IS NOT NULL
  AND t.remind_at <= #{now}
  AND NOT t.reminder_dismissed
  AND t.tenant_id = #{tenantId}
ORDER BY t.remind_at ASC

mapper.update:
UPDATE tasks
SET reminder_dismissed = true
WHERE id = #{id} AND type = 'RECORD' AND tenant_id = #{tenantId}
